  event?: Prisma.EventOmit;
  searchIndex?: Prisma.SearchIndexOmit;
  space?: Prisma.SpaceOmit;
  object?: Prisma.ObjectOmit;
  reminder?: Prisma.ReminderOmit;
  notification?: Prisma.NotificationOmit;
  timeline?: Prisma.TimelineOmit;
